// Generated by secure-by-design v0.1.0 for ISO 27001 A.8.15 + DPDP §8 accountability.
// Reads from ../../privacy-security-manifest.yaml.
// Safe to modify. Safe to delete. Re-run /sbd-deploy to regenerate.
// Docs: docs/scaffolds/audit-log.md
//
// Structured, PII-redacting audit logger. ALL security-relevant events go through here.
// Use auditLog.event(...) for normal events. Use auditLog.security(...) for auth/authz.

import { createHash } from 'node:crypto';

export type Severity = 'INFO' | 'NOTICE' | 'WARN' | 'ERROR' | 'CRITICAL';

export interface AuditEvent {
  timestamp: string;        // ISO 8601
  action: string;           // e.g. 'patient.create', 'dsr.access', 'auth.login.failed'
  actor: string;            // who did it (user/service ID; never raw email/phone)
  target?: string;          // what was acted on (entity ID; never raw PII)
  severity: Severity;
  outcome: 'success' | 'failure' | 'denied';
  attrs?: Record<string, unknown>; // pre-redacted attributes
  requestId?: string;
}

export interface AuditSink {
  write(event: AuditEvent): Promise<void>;
}

// Default sink — replace at boot with your real sink (structured logger, SIEM, etc.).
class StderrSink implements AuditSink {
  async write(event: AuditEvent): Promise<void> {
    // eslint-disable-next-line no-console
    console.error(JSON.stringify({ kind: 'audit', ...event }));
  }
}

let sink: AuditSink = new StderrSink();
export function setAuditSink(s: AuditSink): void { sink = s; }

// Manifest-driven sensitivity tiers. Wired up at boot from privacy-security-manifest.yaml.
let sensitiveFieldNames = new Set<string>();
export function configureRedaction(fields: string[]): void {
  sensitiveFieldNames = new Set(fields.map(f => f.toLowerCase()));
}

const COMMON_PII_PATTERNS: RegExp[] = [
  /\b[\w.+-]+@[\w-]+(?:\.[\w-]+)+\b/g,        // emails
  /\b(?:\+?91[-\s]?)?[6-9]\d{9}\b/g,           // Indian phone numbers
  /\b\d{4}\s?\d{4}\s?\d{4}\b/g,                // Aadhaar-like
  /\b[A-Z]{5}\d{4}[A-Z]\b/g,                   // PAN
];

function pseudonymize(value: string): string {
  return 'pii:' + createHash('sha256').update(value).digest('hex').slice(0, 12);
}

export function redact<T>(value: T): T {
  if (value == null) return value;
  if (typeof value === 'string') {
    let s = value;
    for (const re of COMMON_PII_PATTERNS) {
      s = s.replace(re, (m) => pseudonymize(m));
    }
    return s as unknown as T;
  }
  if (Array.isArray(value)) {
    return value.map((v) => redact(v)) as unknown as T;
  }
  if (typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      if (sensitiveFieldNames.has(k.toLowerCase())) {
        out[k] = typeof v === 'string' ? pseudonymize(v) : '[REDACTED]';
      } else {
        out[k] = redact(v);
      }
    }
    return out as unknown as T;
  }
  return value;
}

async function emit(event: Omit<AuditEvent, 'timestamp'>): Promise<void> {
  const full: AuditEvent = {
    timestamp: new Date().toISOString(),
    ...event,
    attrs: event.attrs ? redact(event.attrs) : undefined,
  };
  await sink.write(full);
}

export const auditLog = {
  /** Standard event — data mutation, resource access, etc. */
  event(action: string, fields: Partial<Omit<AuditEvent, 'action' | 'timestamp'>> = {}): Promise<void> {
    return emit({
      action,
      actor: fields.actor ?? 'unknown',
      target: fields.target,
      severity: fields.severity ?? 'INFO',
      outcome: fields.outcome ?? 'success',
      attrs: fields.attrs,
      requestId: fields.requestId,
    });
  },

  /** Auth/authz event. Always logged at NOTICE or higher; failures at WARN. */
  security(action: string, fields: Partial<Omit<AuditEvent, 'action' | 'timestamp'>> = {}): Promise<void> {
    return emit({
      action,
      actor: fields.actor ?? 'unknown',
      target: fields.target,
      severity: fields.severity ?? (fields.outcome === 'failure' ? 'WARN' : 'NOTICE'),
      outcome: fields.outcome ?? 'success',
      attrs: fields.attrs,
      requestId: fields.requestId,
    });
  },
};
